H.background();
const v = H.plot2d({ xMin: 0, xMax: 20, yMin: -3, yMax: 7 });
v.grid(); v.axes();
const v0 = P.v0, mu = Math.max(0, P.mu), g = 9.8;
// Friction decelerates: a = -mu*g. Puck slides, stops, then loops.
const a = mu * g;
const tStop = a > 1e-6 ? v0 / a : Infinity;
const dStop = a > 1e-6 ? v0 * v0 / (2 * a) : Infinity;
// loop period: travel + a short pause; if frictionless, just wrap the track.
const period = a > 1e-6 ? tStop + 1.5 : 20 / Math.max(0.1, v0);
const tc = t % period;
let x, vel;
if (a > 1e-6) {
  if (tc < tStop) { x = v0 * tc - 0.5 * a * tc * tc; vel = v0 - a * tc; }
  else { x = dStop; vel = 0; }
} else {
  x = (v0 * tc) % 20; vel = v0;
}
x = Math.min(x, 19.5);
const yTrack = 0;
// track
v.line(0, yTrack, 20, yTrack, { color: H.colors.axis, width: 2 });
// puck
v.circle(x, yTrack + 0.45, 12, { fill: H.colors.accent2, stroke: H.colors.bg, width: 2 });
// velocity arrow (scaled)
if (vel > 0.01) v.arrow(x, yTrack + 1.6, x + Math.min(6, vel * 0.6), yTrack + 1.6, { color: H.colors.good, width: 3 });
// net force arrow (friction, opposes motion) only when moving and mu>0
if (a > 1e-6 && vel > 0.01) v.arrow(x, yTrack + 0.45, x - Math.min(4, a * 0.3), yTrack + 0.45, { color: H.colors.warn, width: 3 });
H.text("Newton's 1st law: no net force → constant velocity", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
const law = (mu < 1e-6) ? "F_net = 0  →  v stays constant" : "F_net = friction  →  v decreases";
H.text(law, 24, 52, { color: H.colors.sub, size: 13 });
H.text("v = " + vel.toFixed(2) + " m/s    x = " + x.toFixed(2) + " m    μ = " + mu.toFixed(2), 24, 74, { color: H.colors.sub, size: 13 });
